#include "stdlib/math/base/special/tanhf.h"
#include "stdlib/math/base/assert/is_nanf.h"


static const float MAXLOGF = 88.72283935546875f; // log(FLT_MAX)

/**
* Define prototypes for external functions.
*/
extern float expf( float x );

/* Begin auto-generated functions. The following functions are auto-generated. Do not edit directly. */

// BEGIN: polyval

/**
* Evaluates a polynomial.
*
* ## Notes
*
* -   The implementation uses [Horner's rule][horners-method] for efficient computation.
*
* [horners-method]: https://en.wikipedia.org/wiki/Horner%27s_method
*
* @param x    value at which to evaluate the polynomial
* @return     evaluated polynomial
*/
static float polyval( const float x ) {
	return -0.333332819422f + (x * (0.133314422036f + (x * (-0.0537397155531f + (x * (0.0206390887954f + (x * -0.00570498872745f)))))));
}

// END: polyval

/* End auto-generated functions. */

/**
* Computes the hyperbolic tangent of a single-precision floating-point number.
*
* ## Method
*
* For \\( |x| < 0.625 \\), we use a rational function of the form (Cody and Waite)
*
* ```tex
* x + x^3 \frac{\mathrm{P}(x)}{\mathrm{Q}(x)}
* ```
*
* Otherwise,
*
* ```tex
* \begin{align*}
* \operatorname{tanhf}(x) &= \frac{\operatorname{sinhf}(x)}{\operatorname{coshf}(x)} \\
* &= 1 - \frac{2}{e^{2x} + 1}
* \end{align*}
* ```
*
* ## Notes
*
* -   Relative error:
*
*     | arithmetic | domain | # trials | peak    | rms     |
*     |:----------:|:------:|:--------:|:-------:|:-------:|
*     | IEEE       | -2,2   | 100000   | 1.3e-7  | 2.6e-8  |
*
* @param x    input value
* @return     output value
*
* @example
* float out = stdlib_base_tanhf( 0.0f );
* // returns 0.0f
*/
float stdlib_base_tanhf( const float x ) {
	float ax;
	float z;

	// Handle +-0 to preserve sign & nan values:
	if( stdlib_base_is_nanf( x ) || x == 0.0f) {
		return x;
	}
	if ( x < 0.0f ) {
		ax = -x;
	} else {
		ax = x;
	}
	if ( ax > 0.5f * MAXLOGF ) {
		if ( x > 0.0f ) {
			return 1.0f;
		}
		return -1.0f;
	}
	if ( ax >= 0.625f ) {
		ax = expf( ax + ax );
		z = 1.0f - 2.0f/( ax + 1.0f );
		if( x < 0.0f ) {
			z = -z;
		}
	}
	else {
		z = ax * ax;
		z = x + ( x * z * polyval( z ) );
	}
	return z;
}
